  ui_story_33010401_101_dialog_content = "\"Permata yang menyala akan menunjukkan pemandangan terindah di dunia kepada kamu, tetapi juga akan merenggut nyawamu.\"",
  ui_story_33010401_102_dialog_content = "\"Saat kamu melihatnya adalah saat kamu mati.\"",
