  ui_story_33010401_112_dialog_content = "Dengan keindahan tertinggi dalam genggamanku, aku tidak perlu hidup lagi.",
  ui_story_33010401_113_dialog_content = "Jangan berbuat bodoh, Anthony!",
  ui_story_33010401_114_dialog_content = "Kecantikan adalah tentang meruntuhkan batasan dan membuat pengorbanan tanpa alasan...",
  ui_story_33010401_115_dialog_content = "Ini adalah apa yang aku bersedia tukarkan dengan hidupku.",
  ui_story_33010401_116_dialog_content = "Anthony!",
